targets.expr:
sum(
  vault_token_count_by_auth{
    job=~"$job",
instance=~"$instance"

,
cluster=~"$exported_cluster"
,
namespace=~"$exported_namespace"

  }
)

(
  1 -
  (
    sum(
      rate(
        vault_core_response_status_code{
          job=~"$job",
instance=~"$instance"

,
          type="5xx"
        }[$__rate_interval]
      )
    )
    /
    sum(
      rate(
        vault_core_response_status_code{
          job=~"$job",
instance=~"$instance"


        }[$__rate_interval]
      )
    )
  )
)
* 100

sum by (instance) (
  vault_core_unsealed{
    job=~"$job",
instance=~"$instance"

,
cluster=~"$exported_cluster"

  }
)

sum by (type) (
  rate(
    vault_core_response_status_code{
      job=~"$job",
instance=~"$instance"


    }[$__rate_interval]
  )
)

sum by (type) (
  rate(
    vault_core_response_status_code{
      job=~"$job",
instance=~"$instance"


    }[$__rate_interval]
  )
)

(
  1 -
  (
    sum(
      rate(
        vault_core_response_status_code{
          job=~"$job",
instance=~"$instance"

,
          type="5xx"
