sum by (route) (
  rate(
    label_replace(
      {
        __name__=~"vault_route_read_.+__count",
        job=~"$job",
instance=~"$instance"


      },
      "route", "$1", "__name__", "vault_route_read_(.+)__count"
    )[$__rate_interval:]
  )
)

(
  sum by (route) (
    rate(
      label_replace(
        {
          __name__=~"vault_route_read_.+__sum",
          job=~"$job",
instance=~"$instance"


        },
        "route", "$1", "__name__", "vault_route_read_(.+)__sum"
      )[$__rate_interval:]
    )
  )
  /
  sum by (route) (
    rate(
      label_replace(
        {
          __name__=~"vault_route_read_.+__count",
          job=~"$job",
instance=~"$instance"


